import '../state/player_event_journal.dart';
import '../state/runtime_game_state.dart';

/// Shared data-driven visibility rules for dialogue nodes and choices.
class DialogueConditions {
  const DialogueConditions({
    this.requiredFlags = const {},
    this.excludedFlags = const {},
    this.requiredFactIds = const {},
    this.unknownFactIds = const {},
    this.requiredSeenNodeIds = const {},
    this.unseenNodeIds = const {},
    this.minimumAffinity,
    this.maximumAffinity,
    this.minimumRelationshipLevel = 0,
    this.events = const [],
  }) : assert(minimumAffinity == null || minimumAffinity >= 0),
       assert(maximumAffinity == null || maximumAffinity >= 0),
       assert(minimumRelationshipLevel >= 0);

  final Set<String> requiredFlags;
  final Set<String> excludedFlags;
  final Set<String> requiredFactIds;
  final Set<String> unknownFactIds;
  final Set<String> requiredSeenNodeIds;
  final Set<String> unseenNodeIds;
  final int? minimumAffinity;
  final int? maximumAffinity;
  final int minimumRelationshipLevel;
  final List<PlayerEventCondition> events;

  bool matches(
    NpcRelationshipState relationship, {
    PlayerEventJournal? journal,
    double activePlaySeconds = 0,
  }) {
    final activeJournal = journal ?? PlayerEventJournal();
    return (minimumAffinity == null ||
            relationship.affinity >= minimumAffinity!) &&
        (maximumAffinity == null ||
            relationship.affinity <= maximumAffinity!) &&
        relationship.level >= minimumRelationshipLevel &&
        relationship.flags.containsAll(requiredFlags) &&
        !relationship.flags.any(excludedFlags.contains) &&
        relationship.learnedFactIds.containsAll(requiredFactIds) &&
        !relationship.learnedFactIds.any(unknownFactIds.contains) &&
        relationship.seenDialogueIds.containsAll(requiredSeenNodeIds) &&
        !relationship.seenDialogueIds.any(unseenNodeIds.contains) &&
        events.every(
          (condition) =>
              activeJournal.matches(condition, nowSeconds: activePlaySeconds),
        );
  }

  factory DialogueConditions.fromJson(Map<String, Object?> json) {
    return DialogueConditions(
      requiredFlags: _optionalStringSet(json, 'requiredFlags'),
      excludedFlags: _optionalStringSet(json, 'excludedFlags'),
      requiredFactIds: _optionalStringSet(json, 'requiredFactIds'),
      unknownFactIds: _optionalStringSet(json, 'unknownFactIds'),
      requiredSeenNodeIds: _optionalStringSet(json, 'requiredSeenNodeIds'),
      unseenNodeIds: _optionalStringSet(json, 'unseenNodeIds'),
      minimumAffinity: json['minimumAffinity'] == null
          ? null
          : _int(json, 'minimumAffinity'),
      maximumAffinity: json['maximumAffinity'] == null
          ? null
          : _int(json, 'maximumAffinity'),
      minimumRelationshipLevel: _optionalInt(
        json,
        'minimumRelationshipLevel',
        fallback: 0,
      ),
      events: [
        for (final (index, value) in _optionalList(json, 'events').indexed)
          _eventConditionFromJson(
            _jsonObject(value, 'conditions.events[$index]'),
          ),
      ],
    );
  }

  Map<String, Object?> toJson() => {
    if (requiredFlags.isNotEmpty)
      'requiredFlags': requiredFlags.toList()..sort(),
    if (excludedFlags.isNotEmpty)
      'excludedFlags': excludedFlags.toList()..sort(),
    if (requiredFactIds.isNotEmpty)
      'requiredFactIds': requiredFactIds.toList()..sort(),
    if (unknownFactIds.isNotEmpty)
      'unknownFactIds': unknownFactIds.toList()..sort(),
    if (requiredSeenNodeIds.isNotEmpty)
      'requiredSeenNodeIds': requiredSeenNodeIds.toList()..sort(),
    if (unseenNodeIds.isNotEmpty)
      'unseenNodeIds': unseenNodeIds.toList()..sort(),
    if (minimumAffinity != null) 'minimumAffinity': minimumAffinity,
    if (maximumAffinity != null) 'maximumAffinity': maximumAffinity,
    if (minimumRelationshipLevel != 0)
      'minimumRelationshipLevel': minimumRelationshipLevel,
    if (events.isNotEmpty)
      'events': [for (final event in events) _eventConditionToJson(event)],
  };
}

/// One authored player response and its bounded relationship effect.
class DialogueChoice {
  const DialogueChoice({
    required this.id,
    required this.text,
    this.affinityDelta = 0,
    this.oneTimeRewardFlag = '',
    this.oneTime = false,
    this.addedFlags = const {},
    this.outcomeTag,
    this.targetNodeId,
    this.endsConversation = false,
    this.giftRuleId,
    this.conditions = const DialogueConditions(),
  }) : assert(id != ''),
       assert(affinityDelta >= -1 && affinityDelta <= 1),
       assert(outcomeTag == null || outcomeTag != ''),
       assert(targetNodeId == null || targetNodeId != ''),
       assert(giftRuleId == null || giftRuleId != ''),
       assert(!endsConversation || targetNodeId == null);

  final String id;
  final String text;
  final int affinityDelta;

  /// Optional authored flag paired with the stable choice [id].
  final String oneTimeRewardFlag;
  final bool oneTime;
  final Set<String> addedFlags;

  /// Optional stable result consumed by routine-aware dialogue integration.
  final String? outcomeTag;
  final String? targetNodeId;
  final bool endsConversation;
  final String? giftRuleId;
  final DialogueConditions conditions;

  bool get isGift => giftRuleId != null;
  bool get hasOneTimeEffect => oneTime || oneTimeRewardFlag.isNotEmpty;

  DialogueChoiceApplication applyTo(
    NpcRelationshipState relationship, {
    int levelOneAffinity = NpcRelationshipState.defaultLevelOneAffinity,
  }) {
    final alreadyApplied =
        hasOneTimeEffect &&
        (relationship.appliedChoiceIds.contains(id) ||
            (oneTimeRewardFlag.isNotEmpty &&
                relationship.flags.contains(oneTimeRewardFlag)));
    if (alreadyApplied) {
      return DialogueChoiceApplication(
        relationship: relationship,
        rewardApplied: false,
        levelIncreased: false,
      );
    }

    final affinityUpdate = relationship.applyAffinityDelta(
      affinityDelta,
      levelOneAffinity: levelOneAffinity,
    );
    return DialogueChoiceApplication(
      relationship: affinityUpdate.relationship.copyWith(
        flags: {
          ...affinityUpdate.relationship.flags,
          if (oneTimeRewardFlag.isNotEmpty) oneTimeRewardFlag,
          ...addedFlags,
        },
        appliedChoiceIds: hasOneTimeEffect
            ? {...affinityUpdate.relationship.appliedChoiceIds, id}
            : affinityUpdate.relationship.appliedChoiceIds,
      ),
      rewardApplied: true,
      levelIncreased: affinityUpdate.levelIncreased,
    );
  }

  factory DialogueChoice.fromJson(Map<String, Object?> json) {
    return DialogueChoice(
      id: _string(json, 'id'),
      text: _string(json, 'text'),
      affinityDelta: _optionalInt(json, 'affinityDelta', fallback: 0),
      oneTime: _optionalBool(json, 'oneTime', fallback: false),
      oneTimeRewardFlag: _optionalString(
        json,
        'oneTimeRewardFlag',
        fallback: '',
      ),
      addedFlags: _optionalStringSet(json, 'addedFlags'),
      outcomeTag: _nullableString(json, 'outcomeTag'),
      targetNodeId: _nullableString(json, 'targetNodeId'),
      endsConversation: _optionalBool(
        json,
        'endsConversation',
        fallback: false,
      ),
      giftRuleId: _nullableString(json, 'giftRuleId'),
      conditions: json['conditions'] == null
          ? const DialogueConditions()
          : DialogueConditions.fromJson(
              _jsonObject(json['conditions'], 'conditions'),
            ),
    );
  }

  Map<String, Object?> toJson() => {
    'id': id,
    'text': text,
    if (targetNodeId != null) 'targetNodeId': targetNodeId,
    if (affinityDelta != 0) 'affinityDelta': affinityDelta,
    if (oneTime) 'oneTime': true,
    if (oneTimeRewardFlag.isNotEmpty) 'oneTimeRewardFlag': oneTimeRewardFlag,
    if (addedFlags.isNotEmpty) 'addedFlags': addedFlags.toList()..sort(),
    if (outcomeTag != null) 'outcomeTag': outcomeTag,
    if (endsConversation) 'endsConversation': true,
    if (giftRuleId != null) 'giftRuleId': giftRuleId,
    if (conditions.toJson().isNotEmpty) 'conditions': conditions.toJson(),
